using Microsoft.Data.Sqlite; using Workbench.Storage.Database;
namespace Workbench.Storage.Workers;
public sealed record StoredCompletionPackage(Guid PackageId,Guid ProjectId,Guid TaskId,Guid ExecutionId,Guid RevisionId,string Report,string Evidence,DateTimeOffset CreatedAt);
public sealed class CompletionPackageRepository(WorkbenchDatabase database){private readonly WorkbenchDatabase _d=database; public async Task AddAsync(Guid id,Guid executionId,Guid taskId,Guid revisionId,string report,string evidence, CancellationToken ct=default){if(!evidence.Contains("schema_version",StringComparison.Ordinal))throw new InvalidOperationException("Evidence schema_version is required.");await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO worker_completion_packages(id,execution_id,task_id,executed_against_revision_id,final_report,evidence_json,created_at) SELECT $i,$e,$t,$r,$f,$v,$a WHERE EXISTS(SELECT 1 FROM worker_executions e JOIN tasks t ON t.id=e.task_id JOIN task_revisions r ON r.task_id=t.id WHERE e.id=$e AND e.task_id=$t AND e.project_id=t.project_id AND r.id=$r)";q.Parameters.AddWithValue("$i",id.ToString());q.Parameters.AddWithValue("$e",executionId.ToString());q.Parameters.AddWithValue("$t",taskId.ToString());q.Parameters.AddWithValue("$r",revisionId.ToString());q.Parameters.AddWithValue("$f",report);q.Parameters.AddWithValue("$v",evidence);q.Parameters.AddWithValue("$a",DateTimeOffset.UtcNow.ToString("O"));if(await q.ExecuteNonQueryAsync(ct)!=1)throw new InvalidOperationException("Completion package ownership mismatch.");} public async Task<StoredCompletionPackage?> GetByExecutionAsync(Guid project,Guid execution,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="SELECT p.id,t.project_id,p.task_id,p.execution_id,p.executed_against_revision_id,p.final_report,p.evidence_json,p.created_at FROM worker_completion_packages p JOIN tasks t ON t.id=p.task_id WHERE p.execution_id=$e AND t.project_id=$p";q.Parameters.AddWithValue("$e",execution.ToString());q.Parameters.AddWithValue("$p",project.ToString());await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?new(Guid.Parse(r.GetString(0)),Guid.Parse(r.GetString(1)),Guid.Parse(r.GetString(2)),Guid.Parse(r.GetString(3)),Guid.Parse(r.GetString(4)),r.GetString(5),r.GetString(6),DateTimeOffset.Parse(r.GetString(7))):null;}}
